DROP TABLE IF EXISTS `repertory_remedies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `repertory_remedies` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `repertory_id` int(11) NOT NULL,
  `remedy_id` int(11) NOT NULL,
  `grade` enum('1','2','3','4') DEFAULT '2',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `is_verified` tinyint(1) NOT NULL DEFAULT 0,
  `verified_source` varchar(100) DEFAULT NULL,
  `verified_page` int(11) DEFAULT NULL,
  `verified_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_rubric_remedy` (`repertory_id`,`remedy_id`),
  KEY `idx_repertory` (`repertory_id`),
  KEY `idx_remedy` (`remedy_id`),
  KEY `idx_repertory_remedies_verified` (`is_verified`,`verified_source`)
) ENGINE=InnoDB AUTO_INCREMENT=694182 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
